mapper.select:
select sys_id, subscription_sys_id, provider, provider_store_id, provider_invoice_id, charge_kind,
       amount, refunded_amount, currency, status, attempt_count, provider_updated_at,
       period_start_at, period_end_at, paid_at, apply_result, insert_user_id
from sys_subscription_invoice
where provider = #{provider}
and provider_store_id = #{providerStoreId}
and provider_invoice_id = #{providerInvoiceId}
for update
